module TriangleCounter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] a1,\n    input wire [15:0] a2,\n    input wire [15:0] a3,\n    input wire [15:0] a4,\n    input wire [15:0] a5,\n    input wire [15:0] a6,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] FINISH = 2'd2;\n    \n    reg [1:0] state;\n    reg [15:0] reg_a1, reg_a2, reg_a3, reg_a5;\n    \n    // Combinational intermediates\n    wire [31:0] sum_sq;\n    wire [31:0] a1_sq, a3_sq, a5_sq;\n    wire [31:0] sum;\n    wire [31:0] sum_squared;\n    \n    // Compute sum: a1 + a2 + a3 (max 3000 < 2^12)\n    assign sum = {16'd0, reg_a1} + {16'd0, reg_a2} + {16'd0, reg_a3};\n    \n    // Compute sum^2 (max 3000^2 = 9,000,000 < 2^24)\n    assign sum_squared = sum * sum;\n    \n    // Compute individual squares\n    assign a1_sq = {16'd0, reg_a1} * {16'd0, reg_a1};\n    assign a3_sq = {16'd0, reg_a3} * {16'd0, reg_a3};\n    assign a5_sq = {16'd0, reg_a5} * {16'd0, reg_a5};\n    \n    // Final computation: (a1+a2+a3)^2 - a1^2 - a3^2 - a5^2\n    assign sum_sq = sum_squared - a1_sq - a3_sq - a5_sq;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            reg_a1 <= 16'd0;\n            reg_a2 <= 16'd0;\n            reg_a3 <= 16'd0;\n            reg_a5 <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Register inputs on start\n                        reg_a1 <= a1;\n                        reg_a2 <= a2;\n                        reg_a3 <= a3;\n                        reg_a5 <= a5;\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    // Single cycle combinational calculation\n                    result <= sum_sq;\n                    state <= FINISH;\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule